  UPDATE feeds SET enabled = false WHERE publisher_id = 1043 AND feed_url = 'https://www.milliyet.com.tr/rss/rssnew/sondakikarss.xml' AND feed_type = 'rss' AND enabled;
  GET DIAGNOSTICS k = ROW_COUNT; IF k <> 1 THEN RAISE EXCEPTION 'old RSS feed: % rows, expected 1 - nothing changed', k; END IF;
  INSERT INTO feeds (publisher_id, feed_url, feed_type, crawl_frequency_minutes, enabled, respect_robots_txt,
                     allowed_domains, category_urls, article_url_patterns, parser_config)
  VALUES (1043, 'https://www.milliyet.com.tr/son-dakika-haberleri/', 'html', 30, true, true, ARRAY['www.milliyet.com.tr', 'uzmanpara.milliyet.com.tr']::text[], ARRAY['https://www.milliyet.com.tr/gundem/', 'https://www.milliyet.com.tr/dunya/', 'https://www.milliyet.com.tr/ekonomi/', 'https://www.milliyet.com.tr/siyaset/']::text[], ARRAY['/gundem/*-*', '/dunya/*-*', '/ekonomi/*-*', '/siyaset/*-*', '/uzmanpara/*-*']::text[], '{}'::jsonb);
